# toy transpiler: Python expression -> JavaScript expression (same abstraction level)
import ast

def js(node):
    if isinstance(node, ast.BinOp):
        op = {'Add': '+', 'Mult': '*', 'Sub': '-', 'Div': '/'}[type(node.op).__name__]
        return '(%s %s %s)' % (js(node.left), op, js(node.right))
    if isinstance(node, ast.Constant):
        return repr(node.value)
    if isinstance(node, ast.Name):
        return node.id
    raise ValueError('untranslatable: %s (flag, never silently approximate)' % type(node).__name__)

src = 'price * (1 + tax)'
print('py:', src)
print('js:', js(ast.parse(src, mode='eval').body))

import ast

class Desugar(ast.NodeTransformer):  # pass 1: listcomp -> explicit loop form
    def visit_ListComp(self, node):
        return ast.Call(func=ast.Name(id='list_of', ctx=ast.Load()),
                         args=[node], keywords=[])

class MapBuiltins(ast.NodeTransformer):  # pass 2: map builtins
    def visit_Call(self, node):
        self.generic_visit(node)
        if isinstance(node.func, ast.Name) and node.func.id == 'list_of':
            node.func.id = 'Array_from'
        return node

tree = ast.parse('ys = [f(x) for x in xs]\n')
for p in (Desugar(), MapBuiltins()):
    tree = p.visit(tree)
print(ast.dump(tree.body[0].value)[:120], '...')
print('pipeline: desugar -> map builtins -> emit (dump the tree between passes)')

# API mapping table with argument adaptation
API = {
    'os.path.join': ('path.join', lambda args: args),                    # 1:1
    'str.upper': ('s.toUpperCase()', lambda args: []),                   # method shift
    'os.getcwd': ('process.cwd()', lambda args: []),
}

def translate(call, args):
    if call not in API:
        return 'ERROR: no mapping for %s (needs a shim)' % call
    target, adapt = API[call]
    return '%s(%s)' % (target, ', '.join(adapt(args)))

print(translate('os.path.join', ['"a"', '"b"']))
print(translate('os.getcwd', []))
print(translate('os.fork', []))

# same logic, three error idioms: the translator must map the IDIOM
# Python:  try: v = parse(s) except ParseError: v = default
# Go:      v, err := parse(s); if err != nil { v = default }
# Rust:    let v = parse(s).unwrap_or(default);

def parse_py(s):
    if not s.isdigit():
        raise ValueError('bad')
    return int(s)

def parse_go_style(s):  # (value, err) tuple
    return (int(s), None) if s.isdigit() else (0, 'bad')

for s in ('42', 'xx'):
    try:
        v = parse_py(s)
    except ValueError:
        v = -1
    v2, err = parse_go_style(s)
    if err:
        v2 = -1
    print('input %-4r py-idiom=%d go-idiom=%d (same behavior, different shape)' % (s, v, v2))

import random
random.seed(9)

def src(xs):
    return sum(x * 2 for x in xs)

def tgt(xs):
    return sum(2 * x for x in xs)

# layer 1: translated unit tests
assert tgt([]) == 0 and tgt([3]) == 6
# layer 2: differential fuzz
bad = 0
for _ in range(1000):
    xs = [random.randint(-1000, 1000) for _ in range(random.randint(0, 20))]
    bad += src(xs) != tgt(xs)
print('layer 1 (unit tests): pass')
print('layer 2 (1000 fuzz cases): %d divergences' % bad)
print('layer 3: human reviews flagged constructs (concurrency, floats, platform APIs)')

# score translators per domain, not just in aggregate
results = {
    'algorithms': {'compile': 0.99, 'tests': 0.97},
    'web-services': {'compile': 0.80, 'tests': 0.45},
    'concurrency': {'compile': 0.70, 'tests': 0.30},
}
print('%-14s %8s %8s' % ('domain', 'compile', 'tests'))
for d, m in results.items():
    print('%-14s %8.0f%% %8.0f%%' % (d, m['compile'] * 100, m['tests'] * 100))
print('99% on algorithms + 45% on web services = a demo, not a tool')
